    "id": "ab-supercell-32c51066-9a60-4bc8-8c82-a8f52080c200",
    "title": "MarTech Engineer",
    "company": "Supercell",
    "locations": [
      "Helsinki",
      "London"
    ],
    "remote": false,
    "rkind": null,
